// src/pages/ContactPage.js
import { useState } from 'react';
import { Link } from 'react-router-dom';
import styles from '../styles/ContactPage.module.css';
import mapPlaceholder from '../assets/map_placeholder.png';

function ContactPage() {
  const [darkMode, setDarkMode] = useState(false);
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    message: '',
  });
  const [submitted, setSubmitted] = useState(false);

  const toggleTheme = () => setDarkMode(prev => !prev);

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value,
    });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    setSubmitted(true);
    console.log('Form submitted:', formData);
    alert(`Thanks, ${formData.name}! Message received.`);
  };

  return (
    <div className={darkMode ? styles['dark-mode'] : ''}>
      <header className={styles.header}>
        <h1>Contact Me</h1>
        <nav>
          <ul className={styles.navList}>
            <li><Link to="/">Home</Link></li>
            <li><Link to="/about">About</Link></li>
            <li><Link to="/contact" className={styles.active}>Contact</Link></li>
            <li><Link to="/register">Register</Link></li>
            <li><Link to="/game">Game</Link></li>
          </ul>
        </nav>
      </header>

      <button className={styles.themeToggle} onClick={toggleTheme}>
        Toggle Dark/Light
      </button>

      {!submitted ? (
        <section>
          <form onSubmit={handleSubmit} className={styles.contactForm}>
            <label>Name</label>
            <input
              type="text"
              name="name"
              value={formData.name}
              onChange={handleChange}
              placeholder="Enter your name"
              required
            />

            <label>Email</label>
            <input
              type="email"
              name="email"
              value={formData.email}
              onChange={handleChange}
              placeholder="example@email.com"
              required
            />

            <label>Message</label>
            <textarea
              name="message"
              rows="5"
              value={formData.message}
              onChange={handleChange}
              placeholder="Type your message here..."
              required
            />

            <input type="submit" value="Submit" />
          </form>
        </section>
      ) : (
        <p className={styles.successMsg}>
          Thank you! We will get back to you soon.
        </p>
      )}

      <section>
        <h3>Helpful Resources</h3>
        <table>
          <thead>
            <tr>
              <th>Resource Name</th>
              <th>Description</th>
            </tr>
          </thead>
          <tbody>
            <tr>
              <td>W3Schools</td>
              <td>Online tutorials for HTML, CSS, and web development</td>
            </tr>
            <tr>
              <td>MDN Web Docs</td>
              <td>Official documentation for web technologies</td>
            </tr>
            <tr>
              <td>FreeCodeCamp</td>
              <td>Learn coding through interactive lessons</td>
            </tr>
          </tbody>
        </table>
      </section>

      <section>
        <h3>Location</h3>
        <img src={mapPlaceholder} alt="Map placeholder showing location" width="600" />
      </section>

      <section className={styles.links}>
        <h3>External Links</h3>
        <a href="https://www.w3schools.com" target="_blank">W3Schools</a>
        <a href="https://developer.mozilla.org" target="_blank">MDN Web Docs</a>
        <a href="https://www.freecodecamp.org" target="_blank">FreeCodeCamp</a>
      </section>

      <footer className={styles.footer}>
        <p>Contact: dxxxxxxxxxxx@gmail.com | Phone: 09xxxxxxx8</p>
        <p>&copy; 2026 My Personal Portfolio. All rights reserved.</p>
      </footer>
    </div>
  );
}

export default ContactPage;
